/* syrk.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"

/* Optional OpenMP support (pragmas are harmless if OpenMP is disabled). */
#ifdef _OPENMP
# include <omp.h>
#endif

/* Tunable blocking factors.
 * These values are chosen for a modern x64 with sizable caches.
 * Adjust if needed for a different target. */
#ifndef SYRK_TILE_I
# define SYRK_TILE_I 64
#endif

#ifndef SYRK_TILE_J
# define SYRK_TILE_J 64
#endif

#ifndef SYRK_TILE_K
# define SYRK_TILE_K 256
#endif


/* Array initialization.
 *
 * NOTE: We change the *physical* layout of A to improve memory access:
 *   - Original code: A is N x M, row-major, accessed as A[i][k].
 *   - Optimized code: A is allocated as M x N, row-major, and we access
 *     it as A[k][i], i.e., we store A in column-major form logically.
 *
 * Logically, A_logical(i,k) = A_physical[k][i]. We initialize A so that
 * A_logical(i,k) has exactly the same values as in the original code.
 */
static
void init_array(int n, int m,
                DATA_TYPE *alpha,
                DATA_TYPE *beta,
                DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
                DATA_TYPE POLYBENCH_2D(A,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta  = 1.2;

  /* Initialize A:
   * Original semantics: for i in [0,n), j in [0,m):
   *   A_logical[i][j] = ((i*j + 1) % n) / n;
   *
   * Here A is physically A[m][n]; we store:
   *   A_physical[j][i] = A_logical[i][j]
   * so that A_physical[k][i] == A_logical[i][k].
   */
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[j][i] = (DATA_TYPE)(((i * j + 1) % n)) / n;

  /* Initialize C as before (row-major N x N). */
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE)(((i * j + 2) % m)) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied (high-level):
 *   - A is stored logically in column-major form (physical MxN, used as A[k][i]),
 *     which matches an outer-product style syrk update.
 *   - The lower triangle of C is scaled by beta in a separate pass
 *     (cost is O(N^2), negligible vs. O(N^2*M) update).
 *   - The rank-k update is implemented as a blocked outer-product:
 *       for k: C += alpha * A[:,k] * A[:,k]^T
 *     with tiling over i (rows of C), j (columns of C), and k (columns of A).
 *   - Inner-most loop runs over j, giving unit-stride accesses to both
 *     C[i][j] (row-major) and A[j][k] (logical column-major).
 *   - The product alpha * A[i,k] is hoisted once per (i,k) and reused.
 *   - The triangular condition (j <= i) is enforced by bounds on j within
 *     each tile, so that only the lower triangle is updated.
 */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
                                                DATA_TYPE alpha,
                                                DATA_TYPE beta,
                                                DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
                                                DATA_TYPE POLYBENCH_2D(A,M,N,m,n))
{
  int i, j, k;

#pragma scop

  /* ------------------------------------------------------------------
   * 1. Scale the lower triangle of C by beta.
   *    Upper triangle (j > i) is intentionally left unchanged.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++) {
      C[i][j] *= beta;
    }
  }

  /* ------------------------------------------------------------------
   * 2. Blocked outer-product style SYRK update:
   *
   *    C_lower := C_lower + alpha * A * A^T
   *
   *    Using the logical column-major view of A:
   *      A_logical(i,k) = A_physical[k][i]
   *
   *    We compute:
   *      for k in [0, M):
   *        for i in [0, N):
   *          v_i = alpha * A_logical(i,k);
   *          for j in [0, i]:
   *            C[i,j] += v_i * A_logical(j,k);
   *
   *    Tiling over I (rows of C/A), J (cols of C / rows of A),
   *    and K (columns of A) improves cache locality.
   * ------------------------------------------------------------------ */

  const int TI = SYRK_TILE_I;
  const int TJ = SYRK_TILE_J;
  const int TK = SYRK_TILE_K;

  /* Tile over k (columns of A). */
  for (int K = 0; K < _PB_M; K += TK) {
    int Kend = K + TK;
    if (Kend > _PB_M)
      Kend = _PB_M;

    /* Tile over i (rows of C / A). */
    for (int I = 0; I < _PB_N; I += TI) {
      int Iend = I + TI;
      if (Iend > _PB_N)
        Iend = _PB_N;

      for (i = I; i < Iend; ++i) {
        /* For row i, only columns j in [0, i] (lower triangle) are active. */
        int max_j_for_i = i + 1;

        /* Tile over j (columns of C, rows of A in the second factor). */
        for (int J = 0; J < max_j_for_i; J += TJ) {
          int Jend = J + TJ;
          if (Jend > max_j_for_i)
            Jend = max_j_for_i;

          /* Accumulate over the current k-tile. */
          for (k = K; k < Kend; ++k) {
            /* Logical A(i,k) = physical A[k][i]; hoist alpha*A(i,k). */
            DATA_TYPE a_ik = alpha * A[k][i];

            /* Pointers to the current blocks of C and A:
             *   - C[i][J..Jend) is contiguous (row-major).
             *   - A[j][k] is A[k][j] in memory; A[k][J..Jend) is contiguous
             *     because A is allocated as MxN row-major and we fix row k.
             */
            DATA_TYPE *restrict c_row = &C[i][J];
            DATA_TYPE *restrict a_row = &A[k][J];

            int len = Jend - J;

            /* Inner-most loop over j: unit stride for both C and A. */
            for (j = 0; j < len; ++j) {
              c_row[j] += a_ik * a_row[j];
            }
          } /* k */
        }   /* J */
      }     /* i */
    }       /* I */
  }         /* K */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);

  /* A is now allocated as M x N (row-major), and we index it as A[k][i]
   * to obtain a logical column-major N x M layout. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
              POLYBENCH_ARRAY(C),
              POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta,
               POLYBENCH_ARRAY(C),
               POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
