/* syrk.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"


/* Array initialization.
 *
 * IMPORTANT LAYOUT NOTE (optimization):
 * -------------------------------------
 * In the original code, A is logically N x M and stored row-major as A[i][k].
 * For the optimized kernel we store A in *column-major* form to match an
 * outer-product style SYRK:
 *
 *   - Conceptual element:   A_logical[i][k],  0 <= i < N, 0 <= k < M
 *   - Storage used here:    A_storage[k][i]
 *
 * so that column k of A (all rows i) is contiguous in memory. This greatly
 * improves locality when we sweep over columns k and update C with
 * outer products.
 *
 * Initialization is adjusted accordingly: we write A_storage[k][i]
 * with the same value that the original code would have stored at A[i][k].
 */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		/* A is stored as [M][N] (column-major w.r.t. logical A[i][k]) */
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta  = 1.2;

  /* Initialize A: logically A(i,k) = ((i*k+1) % n) / n,
     but stored as column-major: A_storage[k][i]. */
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[j][i] = (DATA_TYPE) ((i * j + 1) % n) / n;

  /* Initialize full C in row-major order. */
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i * j + 2) % m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized implementation overview
   ---------------------------------
   Original semantics (BLAS SYRK, UPLO='L', TRANS='N'):

       C := alpha * A * A^T + beta * C

   with:
       - A is N x M
       - C is N x N
       - Only the lower triangle of C (0 <= j <= i < N) is updated;
         the upper triangle is left unchanged.

   Key optimizations applied:

   1. A is stored in column-major form as A_storage[k][i], i.e.,
      the logical A[i][k] is accessed as A[k][i]. This makes each column
      A[*,k] contiguous in memory.

   2. C's lower triangle is first scaled by beta in a separate pass.

   3. The update is rewritten in an outer-product style:

         for k in 0..M-1:
           for i in 0..N-1:
             v_i = alpha * A[i,k]
             for j in 0..i:
               C[i,j] += v_i * A[j,k]

      With the chosen storage, both A[i,k] and A[j,k] are read from
      contiguous memory when i and j vary, respectively, and C[i,j]
      is updated along contiguous j.

   4. Cache blocking is applied along i, j, and k to keep small tiles
      of C and panels of A in cache.
 */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 /* A is stored as [M][N] (column-major for logical A[i][k]) */
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n))
{
  int i, j, k;
  int I, J, K;

  /* Tile sizes chosen for typical x64 cache hierarchies.
     They may be tuned further for a particular machine. */
  const int tile_i = 64;  /* rows of C (and A's second index)   */
  const int tile_j = 64;  /* columns of C within a row (j <= i) */
  const int tile_k = 64;  /* columns of A (reduction dimension) */

  /* BLAS PARAMS
   * TRANS = 'N'
   * UPLO  = 'L'
   * => Form C := alpha * A * A**T + beta * C.
   * A is N x M (logical)
   * C is N x N (only lower triangle updated)
   */
#pragma scop

  /* --------------------------------------------------------------------
   * 1. Scale only the lower triangle of C by beta.
   *
   *    for i in 0..N-1
   *      for j in 0..i
   *        C[i][j] *= beta;
   *
   * Blocking in i improves locality for large N, but the operation is
   * otherwise identical to the original kernel.
   * ------------------------------------------------------------------ */
  for (I = 0; I < _PB_N; I += tile_i) {
    int i_max = (I + tile_i < _PB_N) ? (I + tile_i) : _PB_N;

    for (i = I; i < i_max; ++i) {
      for (j = 0; j <= i; ++j) {
        C[i][j] *= beta;
      }
    }
  }

  /* --------------------------------------------------------------------
   * 2. Symmetric rank-k update on the lower triangle:
   *
   *    C[i,j] += alpha * sum_k A[i,k] * A[j,k],  for 0 <= j <= i < N.
   *
   * We use an outer-product style, blocked algorithm that exploits the
   * column-major storage of A (A[k][i]):
   *
   *    for K-blocks over k:
   *      for k in K..k_max:
   *        for I-blocks over i:
   *          for i in I..i_max:
   *            v_i = alpha * A[k][i];   // logical A[i][k]
   *            for j in 0..i:
   *              C[i][j] += v_i * A[k][j];  // logical A[j][k]
   *
   * C is row-major, so C[i][j] is contiguous in j, and for fixed k both
   * A[k][i] (as i varies) and A[k][j] (as j varies) are unit-stride.
   * Blocking in i and k keeps small panels in cache; optional j-blocking
   * keeps C-row segments hot.
   * ------------------------------------------------------------------ */
  for (K = 0; K < _PB_M; K += tile_k) {
    int k_max = (K + tile_k < _PB_M) ? (K + tile_k) : _PB_M;

    for (I = 0; I < _PB_N; I += tile_i) {
      int i_max = (I + tile_i < _PB_N) ? (I + tile_i) : _PB_N;

      for (k = K; k < k_max; ++k) {

        /* Process a block of rows i for this column k. */
        for (i = I; i < i_max; ++i) {

          /* alpha * A[i,k], with A stored column-major as A[k][i]. */
          DATA_TYPE aik = alpha * A[k][i];

          /* Only j in [0, i] belong to the lower triangle for this row. */
          int max_j = i + 1; /* exclusive upper bound on j */

          /* Tile the j-dimension within the 0..i prefix of the row. */
          for (J = 0; J < max_j; J += tile_j) {
            int j_end = J + tile_j;
            if (j_end > max_j)
              j_end = max_j;

            /* Inner-most loop over j:
             *  - C[i][j] is contiguous in memory (row-major),
             *  - A[k][j] is contiguous in memory because A is [M][N],
             *    so varying j walks along the second index.
             * This is ideal for SIMD vectorization.
             */
            for (j = J; j < j_end; ++j) {
              /* logical A[j,k] is stored as A[k][j] */
              C[i][j] += aik * A[k][j];
            }
          } /* end j-tiling */
        }   /* end i-loop */
      }     /* end k-loop */
    }       /* end I-tile loop */
  }         /* end K-tile loop */

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  /* A is allocated as [M][N] to implement column-major storage
     for the logical N x M matrix. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
              POLYBENCH_ARRAY(C),
              POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

