/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   ------------------
   Original kernel structure (simplified):

       for i
         for j <= i
           C[i][j] *= beta;
         for k
           for j <= i
             C[i][j] += alpha * A[i][k] * A[j][k];

   This touches each C[i][j] once for scaling and then once per k for the
   update (O(M) loads/stores of C per entry).

   The optimized kernel instead computes, for each lower-triangular entry:

       C[i,j] = beta * C[i,j] + alpha * sum_k A[i,k] * A[j,k]

   with the k-reduction kept entirely in a register:

       dot = 0
       for k: dot += A[i,k] * A[j,k]
       C[i,j] = beta * C[i,j] + alpha * dot

   This reduces C traffic to exactly one load and one store per updated entry.
   The loop nest is also blocked in (i,j) to improve locality, and the k-loop
   is a straight-line inner reduction that the compiler can efficiently
   vectorize.
*/
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  /* Use local restricted pointers to help the compiler with alias analysis.
     C_ is N x N, row-major.
     A_ is N x M, row-major. */
  DATA_TYPE (* __restrict C_)[N] = (DATA_TYPE (*)[N]) C;
  DATA_TYPE (* __restrict A_)[M] = (DATA_TYPE (*)[M]) A;

  /* Hoist scalar parameters into local consts for faster access. */
  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  /* Tile sizes for (i,j) blocking.
     64x64 gives a reasonable C-tile working set size on modern caches,
     but these constants can be tuned if desired. */
  const int TILE_I = 64;
  const int TILE_J = 64;

  int i, j, k;

  //BLAS PARAMS
  //TRANS = 'N'
  //UPLO  = 'L'
  // =>  Form  C := alpha*A*A**T + beta*C.
  //A is NxM
  //C is NxN
#pragma scop
  /* Blocked lower-triangular SYRK:
     - Outer loops tile (i,j) so that a small region of C stays hot in cache.
     - For each (i,j) (with j <= i), we compute a full dot product over k
       in registers and only write C[i][j] once. */
  for (int ii = 0; ii < _PB_N; ii += TILE_I) {
    int i_end = ii + TILE_I;
    if (i_end > _PB_N)
      i_end = _PB_N;

    for (int jj = 0; jj < _PB_N; jj += TILE_J) {
      int j_tile_end = jj + TILE_J;
      if (j_tile_end > _PB_N)
        j_tile_end = _PB_N;

      for (i = ii; i < i_end; ++i) {
        /* For this row i, only the lower-triangular part (0 <= j <= i)
           is updated. Restrict the j-range of the current tile accordingly. */
        int j_start = jj;
        if (j_start > i)
          continue; /* This entire (i, jj..j_tile_end) slice is above the diagonal. */

        int j_end = j_tile_end;
        if (j_end > i + 1)
          j_end = i + 1; /* inclusive upper bound is i, so loop uses i+1. */

        /* Pointer to row i of A: A[i][0..M-1] */
        DATA_TYPE * __restrict Ai = A_[i];

        for (j = j_start; j < j_end; ++j) {
          /* Pointer to row j of A: A[j][0..M-1] */
          DATA_TYPE *Aj = A_[j];

          /* Compute dot product of rows A[i,*] and A[j,*] in a scalar
             accumulator. This keeps the entire k-reduction in registers. */
          DATA_TYPE dot = (DATA_TYPE)0;

          /* The inner k-loop has no loop-carried dependencies other than
             the reduction into 'dot'. This pragma tells GCC it may safely
             vectorize ignoring assumed dependencies. Other compilers will
             simply ignore this pragma. */
#pragma GCC ivdep
          for (k = 0; k < _PB_M; ++k) {
            dot += Ai[k] * Aj[k];
          }

          /* Apply the SYRK update for this (i,j) entry. C[i][j] is read and
             written exactly once here, minimizing memory traffic for C. */
          C_[i][j] = beta_ * C_[i][j] + alpha_ * dot;
        }
      }
    }
  }
#pragma endscop

}


