/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

//BLAS PARAMS
//TRANS = 'N'
//UPLO  = 'L'
// =>  Form  C := alpha*A*A**T + beta*C.
//A is NxM
//C is NxN
#pragma scop
  /* Optimized kernel:
   *
   * 1. Fuse scaling by beta with the rank-k update so that each C[i][j]
   *    is loaded and stored exactly once.  In the original kernel,
   *    C[i][j] was read/written once for scaling and again on every
   *    iteration of the k-loop.
   *
   * 2. For each (i,j) with j <= i, compute a dot product over k:
   *
   *       C[i,j] = beta * C[i,j] + alpha * sum_k A[i,k] * A[j,k]
   *
   *    We keep k as the innermost loop.  A is row‑major, so A[i][k] and
   *    A[j][k] are both accessed with unit stride as k varies, which is
   *    ideal for cache locality and SIMD vectorization.
   *
   * 3. Apply simple 2D blocking on (i,j) so that small tiles of C and
   *    the corresponding rows of A are reused from cache.
   *
   * 4. The triangular condition j <= i is preserved by bounding the j
   *    loops accordingly; entries with j > i are never touched, exactly
   *    as in the original code.
   */
  const int TI = 32; /* tile size along i (rows of C / A)  */
  const int TJ = 32; /* tile size along j (cols of C / rows of A) */

